// HasAccount applies the HasEdge predicate on the "account" edge.
func HasAccount() predicate.UpstreamAccountModel {
	return predicate.UpstreamAccountModel(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AccountTable, AccountColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAccountWith applies the HasEdge predicate on the "account" edge with a given conditions (other predicates).
func HasAccountWith(preds ...predicate.UpstreamAccount) predicate.UpstreamAccountModel {
	return predicate.UpstreamAccountModel(func(s *sql.Selector) {
		step := newAccountStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UpstreamAccountModel) predicate.UpstreamAccountModel {
	return predicate.UpstreamAccountModel(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UpstreamAccountModel) predicate.UpstreamAccountModel {
	return predicate.UpstreamAccountModel(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UpstreamAccountModel) predicate.UpstreamAccountModel {
	return predicate.UpstreamAccountModel(sql.NotPredicates(p))
}
